CREATE COLUMN TABLE "TEST_AP"."ASGP" ("AbsEntry" INTEGER CS_INT NOT NULL , "ServiceGrp" NVARCHAR(3) NOT NULL , "Descrip" NVARCHAR(70), "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, PRIMARY KEY ("AbsEntry", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ASGP_CODE" ON "TEST_AP"."ASGP" ( "ServiceGrp" ASC, "LogInstanc" ASC )